descriptor.templateCss:
.json-widget { font-family: sans-serif; padding: 10px; position: relative; }
.step { margin: 12px 0 16px; }
.step-title { font-weight: 700; margin: 6px 0 10px; }
.hint { color:#666; font-size: 12px; }

.file-drop-zone {
  border: 2px dashed #ccc; border-radius: 4px; padding: 36px;
  text-align: center; margin-top: 6px; cursor: pointer;
  transition: background .2s, border-color .2s;
}
.file-drop-zone.dragover { background:#f0f8ff; border-color:#007acc; }
.file-drop-zone.loaded  { border-color:#16a34a; background:#f6fffa; }

.json-status {
  display:inline-flex; align-items:center; gap:6px;
  font-size:12px; padding:4px 8px; border-radius:999px; margin-top:8px;
  background:#f2f2f2; color:#444;
  -webkit-user-select: none; -ms-user-select: none; user-select: none;
}
.json-status.ok   { background:#e6f6ea; color:#17683a; border:1px solid #b7e2c4; }
.json-status.ok::before { content:"✓"; font-weight:700; }
.json-status.err  { background:#fdecea; color:#a4000f; border:1px solid #f5c2c7; }
.json-status.err::before { content:"⚠"; font-weight:700; }
.json-status.info { background:#eef2ff; color:#1e40af; border:1px solid #c7d2fe; }
.json-status.info::before { content:"…"; font-weight:700; }

.panel {
  border:1px solid #ddd; background:#fafafa; border-radius:4px; overflow:hidden;
  display:flex; flex-direction:column; margin-top:12px;
}
.panel-title { font-weight:600; padding:8px 10px; background:#f3f3f3; border-bottom:1px solid #e5e5e5; }
#jsonPreview { padding:10px; margin:0; max-height:260px; overflow:auto; white-space:pre-wrap; }

.device-picker { margin-top: 6px; }
.dp-field { width: 100%; max-width: 520px; }
.device-results { margin-top: 8px; max-width: 520px; border:1px solid #eee; border-radius:6px; overflow:hidden; }
.device-result-row {
  display:flex; justify-content:space-between; align-items:center;
  padding:8px 12px; border-top:1px solid #f2f2f2; background:#fff; cursor:pointer;
}
.device-result-row:first-child { border-top:none; }
.device-result-row:hover { background:#f9fbff; }
.device-result-row code { opacity:.75; }

.chosen { margin-top: 8px; padding: 8px 10px; background:#f8fff6; border:1px solid #cde9bf; border-radius:6px; display:inline-flex; gap:8px; align-items:center; }
.chosen .muted { color:#666; }
.btn-link { background:none; border:none; color:#0b66ff; cursor:pointer; text-decoration:underline; padding:0 4px; }

.actions { margin-top: 12px; }
.btn-primary {
  padding: 10px 14px; border:none; border-radius:8px; font-weight:600; cursor:pointer;
  background:#007acc; color:white; box-shadow:0 2px 6px rgba(0,0,0,.12);
}
.btn-primary:disabled { opacity:.5; cursor:not-allowed; }

.loading-overlay {
  position:absolute; inset:0; display:none; align-items:center; justify-content:center; gap:12px;
  background:rgba(255,255,255,.8); z-index:999; pointer-events:all;
}
.loading-overlay.show { display:flex; }
.spinner {
  width:42px; height:42px; border:4px solid #ddd; border-top-color:#007acc;
  border-radius:50%; animation: spin 1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.step-label { display:block; margin: 6px 0; font-weight: 600; }
.tb-select { width: 100%; max-width: 520px; padding: 8px; border-radius: 6px; }

descriptor.controllerScript:
let $scope, utils, translate, attributeService, deviceService;
let importedObj = null;
let selectedDevice = null;

self.onInit = function () {
  const ctx = self.ctx;
  $scope = ctx.$scope;
  utils = $scope.$injector.get(ctx.servicesMap.get("utils"));
  translate = $scope.$injector.get(ctx.servicesMap.get("translate"));
  attributeService = $scope.$injector.get(
    ctx.servicesMap.get("attributeService")
  );
  deviceService = $scope.$injector.get(ctx.servicesMap.get("deviceService"));

  $scope.toastTargetId = "json-import-" + utils.guid();

  // DOM
  const dropZone = document.getElementById("jsonDrop");
  const fileInput = document.getElementById("jsonFileInput");
  const jsonStatus = document.getElementById("jsonStatus");
  const jsonPreview = document.getElementById("jsonPreview");
  const overlay = document.getElementById("loadingOverlay");

  const deviceSelect = document.getElementById("deviceSelect"); // <select>
  const chosenWrap = document.getElementById("deviceChosen");
  const chosenNameEl = document.getElementById("chosenName");
  const chosenIdEl = document.getElementById("chosenId");
  const clearBtn = document.getElementById("clearSelection");

  const btnApply = document.getElementById("btnApply");

  // ---------- helpers ----------
  function setBusy(on, text) {
    if (!overlay) return;
    overlay.classList.toggle("show", !!on);
    overlay.setAttribute("aria-hidden", on ? "false" : "true");
    const t = overlay.querySelector(".loading-text");
    if (t && text) t.textContent = text;
    const root = document.querySelector(".json-widget");
    if (root) root.setAttribute("aria-busy", on ? "true" : "false");
  }

  function pretty(obj) {
    try {
      return JSON.stringify(obj, null, 2);
    } catch (e) {
      return String(obj);
    }
  }

  function setBadge(kind, html) {
    if (!jsonStatus) return;
    jsonStatus.hidden = false;
    jsonStatus.className = "json-status " + (kind || "info");
    jsonStatus.innerHTML = html || "";
  }
  function clearBadge() {
    if (!jsonStatus) return;
    jsonStatus.hidden = true;
    jsonStatus.textContent = "";
  }
  function refreshApplyState() {
    btnApply.disabled = !(importedObj && selectedDevice && selectedDevice.id);
  }

  // ---------- JSON read ----------
  function readJsonFile(file) {
    return new Promise(function (resolve, reject) {
      const name = file && file.name ? file.name : "";
      if (!/\.json$/i.test(name)) {
        reject(new Error("Not a .json file: " + name));
        return;
      }
      if (!file || file.size === 0) {
        reject(new Error("File is empty: " + name));
        return;
      }

      const fr = new FileReader();
      fr.onload = function (e) {
        const text = e && e.target ? e.target.result : "";
        try {
          const obj = JSON.parse(text);
          resolve({ obj, text: pretty(obj), name });
        } catch (err) {
          reject(
            new Error(
              "Invalid JSON: " + (err && err.message ? err.message : err)
            )
          );
        }
      };
      fr.onerror = function (err) {
        reject(err);
      };
      fr.readAsText(file, "utf-8");
    });
  }

  function onJsonSelected(file) {
    setBusy(true, "Reading JSON…");
    clearBadge();
    readJsonFile(file)
      .then(function (res) {
        importedObj = res.obj;
        jsonPreview.textContent = res.text;
        setBadge("ok", "Loaded <code>" + res.name + "</code>");
        if (dropZone) dropZone.classList.add("loaded");
        if ($scope && $scope.showSuccessToast) {
          $scope.showSuccessToast(
            "JSON loaded",
            1200,
            "bottom",
            "left",
            $scope.toastTargetId
          );
        }
      })
      .catch(function (e) {
        console.error(e);
        importedObj = null;
        jsonPreview.textContent = "";
        const msg = e && e.message ? e.message : String(e);
        setBadge("err", msg);
        if (dropZone) dropZone.classList.remove("loaded");
        if ($scope && $scope.showErrorToast) {
          $scope.showErrorToast(
            "Failed to load JSON",
            "bottom",
            "left",
            $scope.toastTargetId
          );
        }
      })
      .finally(function () {
        setBusy(false);
        if (fileInput) fileInput.value = "";
        refreshApplyState();
      });
  }

  // ---------- Load all devices into dropdown ----------
  // Paginates through tenant devices and fills <mat-select>
  function loadAllDevices(maxToLoad) {
    maxToLoad = maxToLoad || 1000;
    setBusy(true, "Loading devices…");

    // --- auth header from TB UI localStorage
    function getJwt() {
      // TB typically stores the token under 'jwt_token' (fallbacks included)
      return (
        localStorage.getItem("jwt_token") ||
        localStorage.getItem("jwt") ||
        localStorage.getItem("token") ||
        ""
      );
    }
    function authHeaders() {
      var token = getJwt();
      return token ? { "X-Authorization": "Bearer " + token } : {};
    }

    function qs(params) {
      var s = Object.keys(params)
        .map(function (k) {
          return encodeURIComponent(k) + "=" + encodeURIComponent(params[k]);
        })
        .join("&");
      return s ? "?" + s : "";
    }

    function safeId(d) {
      try {
        return d && d.id && d.id.id ? d.id.id : "";
      } catch (e) {
        return "";
      }
    }
    function safeName(d) {
      try {
        return d && d.name ? d.name : "";
      } catch (e) {
        return "";
      }
    }

    function populate(devices) {
      deviceSelect.innerHTML = "";
      var ph = document.createElement("option");
      ph.value = "";
      ph.disabled = true;
      ph.selected = true;
      ph.textContent = devices.length
        ? "Select a device"
        : "No devices available";
      deviceSelect.appendChild(ph);

      devices.forEach(function (d) {
        var opt = document.createElement("option");
        var id = safeId(d),
          name = safeName(d);
        opt.value = id;
        opt.textContent = name || id || "Unnamed device";
        opt.setAttribute("data-device-name", name);
        deviceSelect.appendChild(opt);
      });
    }

    function finish(list) {
      try {
        populate(list || []);
      } finally {
        setBusy(false);
      }
    }

    // simple fetch wrapper
    function apiGet(url, params) {
      var full = url + (params ? qs(params) : "");
      return fetch(full, {
        headers: authHeaders(),
        credentials: "same-origin",
      }).then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status + " " + url);
        return r.json();
      });
    }

    // fetch all pages of a TB list endpoint (returns {data, hasNext})
    function fetchAllPages(url) {
      var page = 0,
        pageSize = 100,
        all = [];
      function step() {
        return apiGet(url, {
          page: page,
          pageSize: pageSize,
          sortProperty: "name",
          sortOrder: "ASC",
        }).then(function (body) {
          var chunk = Array.isArray(body) ? body : body.data || [];
          all = all.concat(chunk);
          var hasNext = !!(body && body.hasNext);
          if (hasNext && all.length < maxToLoad) {
            page += 1;
            return step();
          }
          return all.slice(0, maxToLoad);
        });
      }
      return step();
    }

    // 1) who am I?
    apiGet("/api/auth/user")
      .then(function (user) {
        var authority = (user && user.authority) || "";
        var customerId =
          user && user.customerId && user.customerId.id
            ? user.customerId.id
            : null;

        // 2) pick the right list endpoint
        if (authority === "TENANT_ADMIN" || authority === "SYS_ADMIN") {
          return fetchAllPages("/api/tenant/devices");
        } else if (customerId) {
          return fetchAllPages(
            "/api/customer/" + encodeURIComponent(customerId) + "/devices"
          );
        } else {
          // unknown role → try tenant anyway
          return fetchAllPages("/api/tenant/devices");
        }
      })
      .then(function (list) {
        finish(list);
      })
      .catch(function (err) {
        console.error("[widget] device list fetch failed:", err);
        finish([]);
      });
  }

  // Initialize dropdown
  loadAllDevices();

  // Selection handling for <mat-select>
  // Note: mat-select triggers 'selectionChange' on an internal element; listening on 'change' also works in TB widget DOM.
  deviceSelect.addEventListener("change", function (e) {
    var value = e.target.value || "";
    if (!value) {
      selectedDevice = null;
      chosenWrap.hidden = true;
      refreshApplyState();
      return;
    }
    var opt = deviceSelect.options[deviceSelect.selectedIndex];
    var name = opt
      ? opt.getAttribute("data-device-name") || opt.textContent || ""
      : "";
    selectedDevice = { id: value, name: name };
    chosenNameEl.textContent = name;
    chosenIdEl.textContent = value;
    chosenWrap.hidden = false;
    refreshApplyState();
  });

  if (clearBtn) {
    clearBtn.addEventListener("click", function () {
      selectedDevice = null;
      chosenWrap.hidden = true;
      deviceSelect.selectedIndex = 0; // back to placeholder
      refreshApplyState();
    });
  }

  // ---------- Apply (write shared attribute busRouteData) ----------
  if (btnApply) {
    btnApply.addEventListener("click", function () {
      if (!(importedObj && selectedDevice && selectedDevice.id)) return;
      setBusy(true, "Updating shared attribute busRouteData");

      attributeService
        .saveEntityAttributes(
          { entityType: "DEVICE", id: selectedDevice.id },
          "SHARED_SCOPE",
          [{ key: "busRouteData", value: importedObj }]
        )
        .subscribe(
          function success() {
            setBusy(false);
            if ($scope && $scope.showSuccessToast) {
              $scope.showSuccessToast(
                "Updated “busRouteData” successfully",
                1400,
                "bottom",
                "left",
                $scope.toastTargetId
              );
            }
          },
          function fail(err) {
            console.error(err);
            setBusy(false);
            if ($scope && $scope.showErrorToast) {
              $scope.showErrorToast(
                "Update failed",
                "bottom",
                "left",
                $scope.toastTargetId
              );
            }
          }
        );
    });
  }

  // ---------- Drag/drop wiring ----------
  if (dropZone) {
    dropZone.addEventListener("click", function () {
      fileInput && fileInput.click();
    });
    dropZone.addEventListener("dragover", function (e) {
      e.preventDefault();
      dropZone.classList.add("dragover");
    });
    dropZone.addEventListener("dragleave", function (e) {
      e.preventDefault();
      dropZone.classList.remove("dragover");
    });
    dropZone.addEventListener("drop", function (e) {
      e.preventDefault();
      dropZone.classList.remove("dragover");
      const files =
        e && e.dataTransfer && e.dataTransfer.files ? e.dataTransfer.files : [];
      if (files.length) {
        onJsonSelected(files[0]);
      }
    });
  }
  if (fileInput) {
    fileInput.addEventListener("change", function (e) {
      const f = e && e.target && e.target.files ? e.target.files[0] : null;
      if (f) {
        onJsonSelected(f);
      }
    });
  }
};

self.onDestroy = function () {};
self.onResize = function () {};

